Object.assign(window.POC_SRC,{"payback-meter": "\"\"\"\nPayback Meter - proof of concept (pure Python, standard library only).\n\nClaim A (attribute): the real cost of every request can be measured from the serving loop itself\n  (GPU time per decode step, shared by the requests in the batch in proportion to the memory they hold),\n  and it differs a lot from \"average cost per token\".\nClaim B (margin): real gross margin per customer and per use can be computed from that cost and the price\n  list, and a healthy average can hide uses that barely pay or lose money.\nClaim C (payback): a \"payback clock\" per model version can be computed from the weekly gross profit of that\n  version and the week its successor ships.\nClaim D (privacy): an industry-level export can be produced without any customer-level number leaving\n  the provider (k-anonymity: a segment is published only if it holds at least K customers).\n\nFour labs (run(scenario) for the website):\n  1. attribute - one hour of a synthetic serving cluster: activity-based cost vs. average cost per token\n  2. margin    - gross margin per customer, real vs. naive\n  3. payback   - weeks to pay back the training cost of one model version, for three successor dates\n  4. privacy   - what an aggregated export contains, and what it suppresses\n\nHONESTY: the cluster, the customers, their requests, the prices and the training cost are SYNTHETIC\n(fixed seed 11). The cost model is deliberately simple: a decode step costs a fixed part plus a part that\ngrows with the KV-cache tokens held in the batch (decode is memory-bound). Real serving stacks are more\ncomplex; the method (measure per step, allocate by what each request holds) is the point, not the dollars.\n\"\"\"\nimport random, json, math\n\nSEED = 11\nGPU_HOUR_USD = 2.10            # synthetic all-in cost: chip amortisation + power + hosting, per GPU-hour\nGPUS = 8\nBASE_STEP_S = 0.030            # fixed part of one decode step\nKV_STEP_S = 0.0000008          # extra seconds per KV-cache token held in the batch, per step\nPREFILL_S_PER_TOK = 0.00002    # prefill is fast and parallel\nMAX_BATCH = 32\nPRICE = {\"in\": 3.0, \"out\": 15.0, \"cached\": 0.30}   # USD per million tokens (synthetic price list)\n\nCUSTOMERS = [  # name, requests per hour, input tokens (mean), output tokens (mean), cached share of input\n    (\"chat\",   900,   300,  250, 0.0),\n    (\"search\", 600,  3000,  150, 0.0),\n    (\"docs\",   120, 20000,  200, 0.0),\n    (\"coder\",   80, 60000, 1500, 0.5),\n    (\"agent\",  700,  8000,  300, 0.9),\n]\n\ndef requests(seed=SEED):\n    rng = random.Random(seed); out = []\n    for name, n, tin, tout, cached in CUSTOMERS:\n        for _ in range(n):\n            i = max(20, int(rng.gauss(tin, tin * 0.25))); o = max(10, int(rng.gauss(tout, tout * 0.3)))\n            out.append({\"c\": name, \"in\": i, \"out\": o, \"cached\": int(i * cached), \"t\": rng.uniform(0, 3600)})\n    out.sort(key=lambda r: r[\"t\"]); return out\n\ndef price(r):\n    return (r[\"in\"] - r[\"cached\"]) * PRICE[\"in\"] / 1e6 + r[\"cached\"] * PRICE[\"cached\"] / 1e6 + r[\"out\"] * PRICE[\"out\"] / 1e6\n\ndef serve(reqs):\n    \"\"\"Continuous batching on GPUS identical lanes. Returns gpu-seconds per request (activity-based).\"\"\"\n    lanes = [[] for _ in range(GPUS)]\n    for k, r in enumerate(reqs): lanes[k % GPUS].append(r)\n    for lane in lanes:\n        queue = list(lane); active = []\n        while queue or active:\n            while queue and len(active) < MAX_BATCH:\n                r = queue.pop(0); r[\"gpu_s\"] = (r[\"in\"] - r[\"cached\"]) * PREFILL_S_PER_TOK; r[\"left\"] = r[\"out\"]; r[\"kv\"] = r[\"in\"]; active.append(r)\n            kv_total = sum(a[\"kv\"] for a in active)\n            step = BASE_STEP_S + KV_STEP_S * kv_total\n            for a in active:                       # fixed part shared equally, memory part by KV held\n                a[\"gpu_s\"] += BASE_STEP_S / len(active) + KV_STEP_S * kv_total * (a[\"kv\"] / kv_total)\n                a[\"left\"] -= 1; a[\"kv\"] += 1\n            active = [a for a in active if a[\"left\"] > 0]\n    for r in reqs: r[\"cost\"] = r[\"gpu_s\"] * GPU_HOUR_USD / 3600\n    return reqs\n\n_SERVED = {}\ndef lab_attribute():\n    if \"rs\" not in _SERVED: _SERVED[\"rs\"] = serve(requests())   # simulate once, reuse in every lab\n    rs = _SERVED[\"rs\"]; tot_cost = sum(r[\"cost\"] for r in rs); tot_tok = sum(r[\"in\"] + r[\"out\"] for r in rs)\n    per_tok = tot_cost / tot_tok\n    by = {}\n    for r in rs:\n        b = by.setdefault(r[\"c\"], {\"n\": 0, \"cost\": 0.0, \"naive\": 0.0, \"rev\": 0.0})\n        b[\"n\"] += 1; b[\"cost\"] += r[\"cost\"]; b[\"naive\"] += (r[\"in\"] + r[\"out\"]) * per_tok; b[\"rev\"] += price(r)\n    rows = {c: {\"requests\": v[\"n\"], \"cost_usd\": round(v[\"cost\"], 2), \"naive_usd\": round(v[\"naive\"], 2),\n                \"naive_error_pct\": round((v[\"naive\"] - v[\"cost\"]) / v[\"cost\"] * 100, 1)} for c, v in by.items()}\n    worst = max(rows, key=lambda c: abs(rows[c][\"naive_error_pct\"]))\n    return {\"requests\": len(rs), \"gpu_hours\": round(sum(r[\"gpu_s\"] for r in rs) / 3600, 2), \"total_cost_usd\": round(tot_cost, 2),\n            \"rows\": rows, \"worst\": worst, \"worst_error_pct\": rows[worst][\"naive_error_pct\"], \"_by\": by}\n\ndef lab_margin():\n    a = lab_attribute(); by = a[\"_by\"]\n    rev = sum(v[\"rev\"] for v in by.values()); cost = sum(v[\"cost\"] for v in by.values())\n    rows = {c: {\"revenue_usd\": round(v[\"rev\"], 2), \"real_margin_pct\": round((v[\"rev\"] - v[\"cost\"]) / v[\"rev\"] * 100, 1),\n                \"naive_margin_pct\": round((v[\"rev\"] - v[\"naive\"]) / v[\"rev\"] * 100, 1)} for c, v in by.items()}\n    thin = min(rows, key=lambda c: rows[c][\"real_margin_pct\"])\n    return {\"revenue_usd\": round(rev, 2), \"cost_usd\": round(cost, 2), \"gross_margin_pct\": round((rev - cost) / rev * 100, 1),\n            \"rows\": rows, \"thinnest\": thin, \"thinnest_pct\": rows[thin][\"real_margin_pct\"]}\n\nTRAIN_COST_M = 1200.0       # synthetic training cost of one model version, USD millions\nWEEKLY_REV_M = 90.0         # synthetic weekly revenue of that version at its peak, USD millions\n\ndef payback(weeks_to_successor, margin_pct, horizon=52):\n    \"\"\"Weekly gross profit at the peak until the successor ships; then 60% of users move within two weeks,\n    and the rest leave at 10% a week. Returns weeks to pay back (or None) and the share recovered.\"\"\"\n    gp = WEEKLY_REV_M * margin_pct / 100; got = 0.0; share = 1.0; back = None\n    for w in range(1, horizon + 1):\n        if w > weeks_to_successor: share *= 0.55 if w - weeks_to_successor <= 2 else 0.90\n        got += gp * share\n        if back is None and got >= TRAIN_COST_M: back = w\n    return back, round(min(got, 10 * TRAIN_COST_M) / TRAIN_COST_M * 100, 1)\n\ndef lab_payback():\n    m = lab_margin()[\"gross_margin_pct\"]\n    rows = {str(w): dict(zip((\"payback_week\", \"recovered_pct\"), payback(w, m))) for w in (8, 16, 26)}\n    need = math.ceil(TRAIN_COST_M / (WEEKLY_REV_M * m / 100))\n    return {\"margin_pct\": m, \"train_cost_m\": TRAIN_COST_M, \"weekly_rev_m\": WEEKLY_REV_M, \"weeks_needed_at_peak\": need, \"rows\": rows}\n\nK = 2   # with only 5 synthetic customers; a real deployment would use K >= 5\ndef lab_privacy():\n    seg = {\"chat\": \"consumer\", \"search\": \"consumer\", \"docs\": \"enterprise\", \"coder\": \"developer\", \"agent\": \"developer\"}\n    by = lab_attribute()[\"_by\"]; out = {}\n    for c, v in by.items():\n        s = out.setdefault(seg[c], {\"customers\": 0, \"rev\": 0.0, \"cost\": 0.0}); s[\"customers\"] += 1; s[\"rev\"] += v[\"rev\"]; s[\"cost\"] += v[\"cost\"]\n    pub, sup = {}, []\n    for s, v in out.items():\n        if v[\"customers\"] >= K: pub[s] = {\"customers\": v[\"customers\"], \"margin_pct\": round((v[\"rev\"] - v[\"cost\"]) / v[\"rev\"] * 100)}\n        else: sup.append(s)\n    ids_leaked = sum(1 for s in pub for c in seg if c in json.dumps(pub[s]))\n    return {\"k\": K, \"segments\": len(out), \"published\": pub, \"suppressed\": sup, \"customer_ids_in_export\": ids_leaked}\n\ndef run_all():\n    a = lab_attribute(); a.pop(\"_by\")\n    return {\"attribute\": a, \"margin\": lab_margin(), \"payback\": lab_payback(), \"privacy\": lab_privacy()}\n\n# ---------- live lab for the website (poc-lab.js calls run(scenario)) ----------\ndef _ev(frm, to, label, log, state=\"\", ok=False, bad=False):\n    return {\"frm\": frm, \"to\": to, \"label\": label, \"log\": log, \"state\": state, \"ok\": ok, \"bad\": bad}\n\ndef run(sc):\n    \"\"\"Scenarios: attribute | margin | payback | privacy.\"\"\"\n    ev, ck = [], []\n    if sc == \"attribute\":\n        r = lab_attribute(); rows = r[\"rows\"]\n        lo = min(rows, key=lambda c: rows[c][\"naive_error_pct\"]); hi = max(rows, key=lambda c: rows[c][\"naive_error_pct\"])\n        ev += [_ev(\"Q\", \"S\", \"serve\", f\"{r['requests']} requests from 5 customers in one hour, continuous batching on {GPUS} GPUs\", f\"{r['requests']} שאילתות\"),\n               _ev(\"S\", \"M\", \"measure\", f\"every decode step timed and shared by the KV-cache tokens each request holds: {r['gpu_hours']} GPU-hours\", f\"{r['gpu_hours']} שעות שבב\", ok=True),\n               _ev(\"M\", \"L\", \"cost\", f\"total cost ${r['total_cost_usd']} (synthetic ${GPU_HOUR_USD}/GPU-hour)\", f\"${r['total_cost_usd']}\"),\n               _ev(\"M\", \"L\", \"naive\", f\"average cost per token vs. the meter: '{lo}' {rows[lo]['naive_error_pct']:+}% (under-costed), '{hi}' {rows[hi]['naive_error_pct']:+}% (over-costed)\", f\"{rows[lo]['naive_error_pct']:+}% / {rows[hi]['naive_error_pct']:+}%\", bad=True)]\n        ck += [[\"every_request_costed\", True], [\"naive_differs\", abs(r[\"worst_error_pct\"]) > 25]]\n    elif sc == \"margin\":\n        r = lab_margin(); t = r[\"thinnest\"]\n        ev += [_ev(\"L\", \"D\", \"total\", f\"revenue ${r['revenue_usd']}, cost ${r['cost_usd']}: gross margin {r['gross_margin_pct']}%\", f\"{r['gross_margin_pct']}%\", ok=True)]\n        for c, v in r[\"rows\"].items():\n            ev.append(_ev(\"L\", \"D\", c, f\"{c}: real {v['real_margin_pct']}% (naive {v['naive_margin_pct']}%)\", f\"{v['real_margin_pct']}%\", bad=v[\"real_margin_pct\"] < 50))\n        ev.append(_ev(\"D\", \"D\", \"hidden\", f\"the thinnest use is '{t}' at {r['thinnest_pct']}%, invisible in the average\", f\"{r['thinnest_pct']}%\", bad=True))\n        ck += [[\"margin_per_customer\", True], [\"average_hides_thin\", r[\"thinnest_pct\"] < r[\"gross_margin_pct\"] - 20]]\n    elif sc == \"payback\":\n        r = lab_payback()\n        ev += [_ev(\"D\", \"P\", \"inputs\", f\"one model version: training ${r['train_cost_m']:.0f}M, ${r['weekly_rev_m']:.0f}M a week at its peak, margin {r['margin_pct']}%\", f\"{r['weeks_needed_at_peak']} שבועות בשיא\")]\n        for w, v in r[\"rows\"].items():\n            pb = v[\"payback_week\"]\n            ev.append(_ev(\"P\", \"P\", f\"w{w}\", f\"successor after {w} weeks: \" + (f\"paid back in week {pb}\" if pb else \"never paid back within a year\") + f\", {v['recovered_pct']}% recovered\", f\"{v['recovered_pct']}%\", ok=bool(pb), bad=not pb))\n        ck += [[\"clock_computed\", True], [\"window_matters\", r[\"rows\"][\"8\"][\"recovered_pct\"] < r[\"rows\"][\"26\"][\"recovered_pct\"]]]\n    elif sc == \"privacy\":\n        r = lab_privacy()\n        ev += [_ev(\"D\", \"X\", \"aggregate\", f\"{r['segments']} segments built from 5 customers\", f\"{r['segments']} פלחים\"),\n               _ev(\"X\", \"X\", \"publish\", \"published: \" + \", \".join(f\"{s} ({v['customers']} customers, margin {v['margin_pct']}%)\" for s, v in r[\"published\"].items()), f\"{len(r['published'])} פורסמו\", ok=True),\n               _ev(\"X\", \"X\", \"suppress\", \"suppressed (too few customers to hide one): \" + (\", \".join(r[\"suppressed\"]) or \"none\"), f\"{len(r['suppressed'])} הוסתרו\"),\n               _ev(\"X\", \"X\", \"leak\", f\"customer names or per-customer numbers in the export: {r['customer_ids_in_export']}\", f\"{r['customer_ids_in_export']} דליפות\", ok=r[\"customer_ids_in_export\"] == 0)]\n        ck += [[\"no_customer_leak\", r[\"customer_ids_in_export\"] == 0], [\"small_segments_suppressed\", len(r[\"suppressed\"]) >= 1]]\n    return {\"events\": ev, \"checks\": ck}\n\nif __name__ == \"__main__\":\n    print(json.dumps(run_all(), indent=1, ensure_ascii=False))\n", "revenue-nowcaster": "\"\"\"\nRevenue Nowcaster - proof of concept (pure Python, standard library only).\n\nClaim A (signals): single alternative-data proxies disagree about growth, so none of them can be read alone.\nClaim B (fuse): a small state-space model (a Kalman filter on the log of revenue, with a level and a growth\n  rate) can fuse the proxies into one monthly estimate with an honest uncertainty band.\nClaim C (turn): the fused estimate notices a slowdown months before a quarterly report would.\nOpen question D (truth): the proxies must be calibrated against the true revenue. How good is the\n  nowcast when the true number is known only from a few scattered \"run-rate\" announcements?\n\nFour labs (run(scenario) for the website):\n  1. signals  - three proxies, three different growth stories\n  2. fuse     - the filter, calibrated on monthly truth: error and band coverage\n  3. turn     - when does the nowcast flag the slowdown, versus a report three months later\n  4. truth    - the same filter, calibrated only on sparse announcements (the real-world situation)\n\nHONESTY: the \"true\" revenue path, the proxies, their biases and noise are SYNTHETIC (fixed seed 5).\nThe true path is shaped to echo the reported story (about 80-90% growth per three months in the spring,\nabout 12% in October), but every number here is invented. The method is the point.\n\"\"\"\nimport random, math, json\n\nSEED = 5\nMONTHS = 22                       # Jan 2025 .. Oct 2026\n\ndef truth_path():\n    \"\"\"Monthly revenue (USD bn per month), growth slowing from ~25% to ~3.7% a month during 2026.\"\"\"\n    g = [0.24 + 0.02 * (t % 2) if t < 13 else max(0.037, 0.26 - (t - 13) * 0.038) for t in range(MONTHS)]\n    rev = [0.85]\n    for t in range(1, MONTHS): rev.append(rev[-1] * (1 + g[t]))\n    return rev, g\n\ndef proxies(rev, seed=SEED):\n    \"\"\"Three proxies in log space, each with its own bias, drift and noise.\n    card  : company card spend, small firms only, their share falls 2.5%/month -> under-reads growth\n    router: tokens routed via an API gateway, prices fall 4%/month -> over-reads growth\n    panel : social posts and panels, noisy and one month late\"\"\"\n    rng = random.Random(seed); P = {\"card\": [], \"router\": [], \"panel\": []}\n    for t, r in enumerate(rev):\n        lr = math.log(r)\n        P[\"card\"].append(lr - 1.9 - 0.025 * t + rng.gauss(0, 0.03))\n        P[\"router\"].append(lr + 2.3 + 0.04 * t + rng.gauss(0, 0.03))\n        P[\"panel\"].append((math.log(rev[t - 1]) if t else lr) + 0.4 + rng.gauss(0, 0.08))\n    return P\n\ndef growth3(series):  # three-month growth from a log series, in %\n    return [round((math.exp(series[t] - series[t - 3]) - 1) * 100, 1) if t >= 3 else None for t in range(len(series))]\n\ndef calibrate(P, rev, idx, defn_noise=0.0, defn_bias=0.0, seed=SEED):\n    \"\"\"Least squares per proxy: proxy - log(truth) = a + b*t, using only the months in idx.\n    defn_noise: announced numbers are run-rates with mixed definitions; we add that noise to the truth.\"\"\"\n    rng = random.Random(seed + 1); cal = {}\n    obs = {t: math.log(rev[t]) + math.log(1 + defn_bias) + rng.gauss(0, defn_noise) for t in idx}\n    for k, ys in P.items():\n        xs = [t for t in idx]; d = [ys[t] - obs[t] for t in idx]\n        n = len(xs); mx = sum(xs) / n; md = sum(d) / n\n        sxx = sum((x - mx) ** 2 for x in xs) or 1e-9\n        b = sum((x - mx) * (y - md) for x, y in zip(xs, d)) / sxx; a = md - b * mx\n        res = [y - (a + b * x) for x, y in zip(xs, d)]\n        sd = math.sqrt(sum(e * e for e in res) / max(1, n - 2)) if n > 2 else 0.05\n        cal[k] = (a, b, max(sd, 0.03))\n    return cal\n\ndef kalman(P, cal):\n    \"\"\"Local linear trend on log revenue. State [level, slope]. Returns mean and sd of the level per month.\"\"\"\n    x = [P[\"card\"][0] - cal[\"card\"][0], 0.2]; Pm = [[1.0, 0.0], [0.0, 0.05]]\n    q_l, q_s = 0.0004, 0.0009; out = []\n    for t in range(MONTHS):\n        if t:  # predict\n            x = [x[0] + x[1], x[1]]\n            Pm = [[Pm[0][0] + 2 * Pm[0][1] + Pm[1][1] + q_l, Pm[0][1] + Pm[1][1]], [Pm[0][1] + Pm[1][1], Pm[1][1] + q_s]]\n        for k, ys in P.items():  # update with each calibrated proxy\n            a, b, sd = cal[k]; shift = -1 if k == \"panel\" else 0\n            z = ys[t] - (a + b * t); R = sd * sd\n            if k == \"panel\":\n                if t == 0: continue\n                z -= x[1]                       # panel reads last month's level\n            S = Pm[0][0] + R; K0, K1 = Pm[0][0] / S, Pm[1][0] / S; y = z - x[0]\n            x = [x[0] + K0 * y, x[1] + K1 * y]\n            Pm = [[(1 - K0) * Pm[0][0], (1 - K0) * Pm[0][1]], [Pm[1][0] - K1 * Pm[0][0], Pm[1][1] - K1 * Pm[0][1]]]\n        out.append((x[0], math.sqrt(max(Pm[0][0], 1e-9)), x[1]))\n    return out\n\ndef score(est, rev, start=6):\n    err = [abs(math.exp(m) - r) / r * 100 for (m, s, g), r in zip(est, rev)][start:]\n    cov = [abs(m - math.log(r)) <= 1.645 * s for (m, s, g), r in zip(est, rev)][start:]\n    wid = [(math.exp(1.645 * s) - math.exp(-1.645 * s)) * 100 for (m, s, g) in est][start:]\n    return round(sum(err) / len(err), 1), round(sum(cov) / len(cov) * 100), round(sum(wid) / len(wid), 1)\n\ndef lab_signals():\n    rev, g = truth_path(); P = proxies(rev); t = MONTHS - 1\n    tr = growth3([math.log(r) for r in rev])\n    return {\"month\": \"Oct 2026\", \"truth_3m_pct\": tr[t], \"card_3m_pct\": growth3(P[\"card\"])[t], \"router_3m_pct\": growth3(P[\"router\"])[t], \"panel_3m_pct\": growth3(P[\"panel\"])[t]}\n\ndef lab_fuse():\n    rev, g = truth_path(); P = proxies(rev); cal = calibrate(P, rev, list(range(MONTHS)))\n    est = kalman(P, cal); mape, cov, wid = score(est, rev)\n    m, s, gr = est[-1]\n    return {\"mape_pct\": mape, \"coverage_pct\": cov, \"band_width_pct\": wid, \"oct_est_bn_month\": round(math.exp(m), 1), \"oct_true_bn_month\": round(rev[-1], 1),\n            \"oct_band\": [round(math.exp(m - 1.645 * s), 1), round(math.exp(m + 1.645 * s), 1)]}\n\ndef lab_turn():\n    rev, g = truth_path(); P = proxies(rev); cal = calibrate(P, rev, list(range(MONTHS)))\n    est = kalman(P, cal)\n    true_turn = next(t for t in range(13, MONTHS) if g[t] < 0.15)           # true monthly growth below 15%\n    flag = next((t for t in range(13, MONTHS) if est[t][2] < 0.15), None)   # nowcast slope below 15%\n    report = ((true_turn // 3) + 1) * 3 + 1                                   # the quarter's report, a month after it ends\n    names = [\"ינו 25\", \"פבר 25\", \"מרץ 25\", \"אפר 25\", \"מאי 25\", \"יוני 25\", \"יולי 25\", \"אוג 25\", \"ספט 25\", \"אוק 25\", \"נוב 25\", \"דצמ 25\",\n             \"ינו 26\", \"פבר 26\", \"מרץ 26\", \"אפר 26\", \"מאי 26\", \"יוני 26\", \"יולי 26\", \"אוג 26\", \"ספט 26\", \"אוק 26\", \"נוב 26\", \"דצמ 26\", \"ינו 27\"]\n    return {\"true_turn\": names[true_turn], \"nowcast_flag\": names[flag] if flag is not None else None, \"report\": names[min(report, len(names) - 1)],\n            \"lead_months\": (report - flag) if flag is not None else None, \"lag_vs_truth\": (flag - true_turn) if flag is not None else None}\n\ndef lab_truth():\n    rev, g = truth_path(); P = proxies(rev)\n    ann = [2, 7, 11, 14, 17, 20]                                             # six scattered run-rate announcements\n    cal = calibrate(P, rev, ann, defn_noise=0.06, defn_bias=0.06)          # run-rate is not recognised revenue\n    est = kalman(P, cal); mape, cov, wid = score(est, rev)\n    full = lab_fuse()\n    return {\"announcements\": len(ann), \"definition_bias_pct\": 6, \"definition_noise_pct\": 6, \"mape_pct\": mape, \"coverage_pct\": cov, \"band_width_pct\": wid,\n            \"mape_monthly_truth\": full[\"mape_pct\"], \"coverage_monthly_truth\": full[\"coverage_pct\"], \"band_monthly_truth\": full[\"band_width_pct\"]}\n\ndef lab_truth_table(repeats=30):\n    \"\"\"Error and band coverage by the number of run-rate announcements (random months, averaged), next to exact monthly truth.\n    Used by the spec's live knob. The driver turns out to be the definition gap, not only the count.\"\"\"\n    rev, g = truth_path(); P = proxies(rev); rng = random.Random(9); rows = []\n    e, c, w = score(kalman(P, calibrate(P, rev, list(range(MONTHS)))), rev); rows.append([MONTHS, \"exact\", e, c])\n    for n in (16, 12, 8, 6, 4):\n        E = C = 0\n        for r in range(repeats):\n            idx = sorted(rng.sample(range(MONTHS), n))\n            e, c, w = score(kalman(P, calibrate(P, rev, idx, defn_noise=0.06, defn_bias=0.06, seed=100 + r)), rev); E += e; C += c\n        rows.append([n, \"run-rate\", round(E / repeats, 1), round(C / repeats)])\n    return rows\n\ndef run_all():\n    return {\"signals\": lab_signals(), \"fuse\": lab_fuse(), \"turn\": lab_turn(), \"truth\": lab_truth(), \"truth_table\": lab_truth_table()}\n\n# ---------- live lab for the website (poc-lab.js calls run(scenario)) ----------\ndef _ev(frm, to, label, log, state=\"\", ok=False, bad=False):\n    return {\"frm\": frm, \"to\": to, \"label\": label, \"log\": log, \"state\": state, \"ok\": ok, \"bad\": bad}\n\ndef run(sc):\n    \"\"\"Scenarios: signals | fuse | turn | truth.\"\"\"\n    ev, ck = [], []\n    if sc == \"signals\":\n        r = lab_signals()\n        ev += [_ev(\"C\", \"F\", \"card\", f\"card spend says three-month growth in {r['month']}: {r['card_3m_pct']}%\", f\"{r['card_3m_pct']}%\"),\n               _ev(\"R\", \"F\", \"router\", f\"API router traffic says: {r['router_3m_pct']}%\", f\"{r['router_3m_pct']}%\"),\n               _ev(\"N\", \"F\", \"panel\", f\"panels and posts say: {r['panel_3m_pct']}%\", f\"{r['panel_3m_pct']}%\"),\n               _ev(\"T\", \"T\", \"truth\", f\"the synthetic truth: {r['truth_3m_pct']}%\", f\"{r['truth_3m_pct']}%\", bad=True)]\n        spread = max(r[\"card_3m_pct\"], r[\"router_3m_pct\"], r[\"panel_3m_pct\"]) - min(r[\"card_3m_pct\"], r[\"router_3m_pct\"], r[\"panel_3m_pct\"])\n        ck += [[\"proxies_disagree\", spread > 8]]\n    elif sc == \"fuse\":\n        r = lab_fuse()\n        ev += [_ev(\"F\", \"F\", \"calib\", \"each proxy calibrated against monthly truth: bias and drift removed\", \"כיול חודשי\"),\n               _ev(\"F\", \"O\", \"estimate\", f\"Oct 2026: estimate {r['oct_est_bn_month']}bn/month, 90% band {r['oct_band'][0]}-{r['oct_band'][1]}, truth {r['oct_true_bn_month']}\", f\"{r['oct_est_bn_month']}\", ok=True),\n               _ev(\"O\", \"T\", \"score\", f\"mean error {r['mape_pct']}%, the band holds the truth {r['coverage_pct']}% of months\", f\"{r['mape_pct']}% · {r['coverage_pct']}%\", ok=r[\"coverage_pct\"] >= 80)]\n        ck += [[\"filter_runs\", True], [\"error_small\", r[\"mape_pct\"] < 8], [\"band_honest\", r[\"coverage_pct\"] >= 80]]\n    elif sc == \"turn\":\n        r = lab_turn()\n        ev += [_ev(\"T\", \"T\", \"turn\", f\"the true slowdown starts: {r['true_turn']}\", r[\"true_turn\"], bad=True),\n               _ev(\"F\", \"O\", \"flag\", f\"the nowcast flags it: {r['nowcast_flag']} ({r['lag_vs_truth']} months after it starts)\", r[\"nowcast_flag\"] or \"-\", ok=True),\n               _ev(\"O\", \"O\", \"report\", f\"a quarterly report would show it: {r['report']}, {r['lead_months']} months later\", f\"+{r['lead_months']} חודשים\")]\n        ck += [[\"slowdown_flagged\", r[\"nowcast_flag\"] is not None], [\"earlier_than_report\", (r[\"lead_months\"] or 0) > 0]]\n    elif sc == \"truth\":\n        r = lab_truth()\n        ev += [_ev(\"T\", \"F\", \"sparse\", f\"only {r['announcements']} run-rate announcements in 22 months; a run-rate reads ~{r['definition_bias_pct']}% above booked revenue, give or take {r['definition_noise_pct']}%\", f\"{r['announcements']} נקודות\", bad=True),\n               _ev(\"F\", \"O\", \"estimate\", f\"mean error {r['mape_pct']}% (was {r['mape_monthly_truth']}% with monthly truth)\", f\"{r['mape_pct']}%\", bad=r[\"mape_pct\"] > r[\"mape_monthly_truth\"] * 1.5),\n               _ev(\"O\", \"T\", \"score\", f\"the band holds the truth {r['coverage_pct']}% of months (was {r['coverage_monthly_truth']}%), band width {r['band_width_pct']}% (was {r['band_monthly_truth']}%)\", f\"{r['coverage_pct']}%\", bad=r[\"coverage_pct\"] < 80)]\n        ck += [[\"sparse_measured\", True], [\"truth_gap_found\", r[\"coverage_pct\"] < r[\"coverage_monthly_truth\"] or r[\"mape_pct\"] > 2 * r[\"mape_monthly_truth\"]]]\n    return {\"events\": ev, \"checks\": ck}\n\nif __name__ == \"__main__\":\n    print(json.dumps(run_all(), indent=1, ensure_ascii=False))\n", "distillation-watermark": "\"\"\"\nDistillation Watermark - proof of concept (pure Python, standard library only).\n\nThe scheme is the published \"green list\" watermark (Kirchenbauer et al., 2023), on a toy language model:\nbefore each token, the previous token seeds a hash that splits the vocabulary into a green part\n(GAMMA of it) and a red part; the model adds DELTA to the scores of green tokens. A detector that knows\nthe hash counts green tokens and computes a z-score. Text written without the watermark is green about\nGAMMA of the time; watermarked text much more often.\n\nClaim A (prose): in free text, the watermark is detected reliably in a short answer.\nClaim B (rewrite): it survives light paraphrasing.\nClaim C (code): it survives where the money is, in code, where the next token is often nearly certain.\nClaim D (student): a student model trained on our answers inherits a detectable signal.\n\nFour labs (run(scenario) for the website):\n  1. prose      - 100 answers of 200 tokens, high-entropy text\n  2. paraphrase - the same answers after a rewrite that replaces 45% of the tokens\n  3. code       - 100 answers of 200 tokens, low-entropy text (like code)\n  4. student    - a bigram student trained on a corpus where 30% of the text is ours\n\nHONESTY: the language model is a TOY (a random bigram model over 1,000 tokens, fixed seed 3) whose\n\"temperature\" stands in for how free the text is. Real models and real code differ; the published\nweakness of this scheme on low-entropy text is the point. A detection is z > 4 (about 1 false alarm in 30,000).\n\"\"\"\nimport random, math, json, hashlib\nfrom functools import lru_cache\n\nSEED = 3\nV = 1000\nGAMMA, DELTA = 0.25, 2.0\nZ_TH = 4.0\n\n@lru_cache(maxsize=None)\ndef green(prev, tok):\n    h = hashlib.blake2b(f\"{prev}:{tok}\".encode(), digest_size=4).digest()\n    return int.from_bytes(h, \"big\") / 2 ** 32 < GAMMA\n\nclass Toy:\n    \"\"\"Bigram scores: for each previous token, a few 'natural' next tokens get a high score.\n    temp high = many plausible tokens (prose); temp low = one token dominates (code).\"\"\"\n    def __init__(self, seed=SEED):\n        rng = random.Random(seed); self.top = {}\n        for p in range(V): self.top[p] = [(rng.randrange(V), rng.gauss(0, 1)) for _ in range(24)]\n    def dist(self, prev, temp, wm):\n        sc = {}\n        for t, s in self.top[prev]:\n            v = s / temp\n            if wm and green(prev, t): v += DELTA\n            sc[t] = max(sc.get(t, -1e9), v)\n        m = max(sc.values()); ex = {t: math.exp(v - m) for t, v in sc.items()}; z = sum(ex.values())\n        return [(t, e / z) for t, e in ex.items()]\n\ndef sample(d, rng):\n    r = rng.random(); acc = 0.0\n    for t, p in d:\n        acc += p\n        if r <= acc: return t\n    return d[-1][0]\n\ndef generate(model, n, temp, wm, rng, start=None):\n    out = [start if start is not None else rng.randrange(V)]\n    for _ in range(n): out.append(sample(model.dist(out[-1], temp, wm), rng))\n    return out\n\ndef zscore(seq):\n    \"\"\"Standard practice: each (previous, token) pair is scored once, so a repeated loop cannot inflate the score.\"\"\"\n    pairs = set(zip(seq, seq[1:])); T = max(1, len(pairs)); g = sum(1 for a, b in pairs if green(a, b))\n    return (g - GAMMA * T) / math.sqrt(T * GAMMA * (1 - GAMMA))\n\ndef detect_rate(seqs):\n    return round(sum(1 for s in seqs if zscore(s) > Z_TH) / len(seqs) * 100)\n\ndef paraphrase(seq, frac, rng):\n    out = list(seq)\n    for i in range(1, len(out)):\n        if rng.random() < frac: out[i] = rng.randrange(V)\n    return out\n\nN, L = 100, 200\nTEMP_PROSE, TEMP_CODE = 1.6, 0.15\n\ndef lab_prose():\n    m = Toy(); rng = random.Random(SEED + 1)\n    wm = [generate(m, L, TEMP_PROSE, True, rng) for _ in range(N)]; plain = [generate(m, L, TEMP_PROSE, False, rng) for _ in range(N)]\n    return {\"answers\": N, \"tokens\": L, \"detected_pct\": detect_rate(wm), \"false_alarm_pct\": detect_rate(plain),\n            \"mean_z\": round(sum(zscore(s) for s in wm) / N, 1)}\n\ndef lab_paraphrase():\n    m = Toy(); rng = random.Random(SEED + 1)\n    wm = [generate(m, L, TEMP_PROSE, True, rng) for _ in range(N)]\n    rw = [paraphrase(s, 0.45, rng) for s in wm]\n    return {\"replaced_pct\": 45, \"detected_pct\": detect_rate(rw), \"mean_z\": round(sum(zscore(s) for s in rw) / N, 1)}\n\ndef lab_code():\n    m = Toy(); rng = random.Random(SEED + 2)\n    wm = [generate(m, L, TEMP_CODE, True, rng) for _ in range(N)]\n    longer = [generate(m, 1000, TEMP_CODE, True, rng) for _ in range(40)]\n    return {\"answers\": N, \"tokens\": L, \"detected_pct\": detect_rate(wm), \"mean_z\": round(sum(zscore(s) for s in wm) / N, 1),\n            \"detected_1000_pct\": detect_rate(longer)}\n\ndef _student(m, rng, temp, n_ours, n_other):\n    counts = {}\n    corpus = [generate(m, L, temp, True, rng) for _ in range(n_ours)] + [generate(m, L, temp, False, rng) for _ in range(n_other)]\n    for s in corpus:\n        for a, b in zip(s, s[1:]): counts.setdefault(a, {}); counts[a][b] = counts[a].get(b, 0) + 1\n    def gen(n):\n        out = [rng.randrange(V)]\n        for _ in range(n):\n            c = counts.get(out[-1])\n            if not c: out.append(rng.randrange(V)); continue\n            tot = sum(c.values()); r = rng.random() * tot; acc = 0\n            for t, k in c.items():\n                acc += k\n                if r <= acc: out.append(t); break\n        return out\n    return gen\n\ndef lab_student():\n    \"\"\"A bigram 'student' learns from a corpus where 30% of the text is ours (watermarked) and 70% is other text.\n    We sample from the student and run our detector on its answers: once for prose, once for code.\"\"\"\n    m = Toy(); rng = random.Random(SEED + 3)\n    gp = _student(m, rng, TEMP_PROSE, 150, 350); gc = _student(m, rng, TEMP_CODE, 150, 350)\n    return {\"our_share_pct\": 30, \"prose_200_pct\": detect_rate([gp(L) for _ in range(N)]), \"prose_3000_pct\": detect_rate([gp(3000) for _ in range(20)]),\n            \"code_3000_pct\": detect_rate([gc(3000) for _ in range(20)])}\n\ndef run_all():\n    return {\"prose\": lab_prose(), \"paraphrase\": lab_paraphrase(), \"code\": lab_code(), \"student\": lab_student()}\n\n# ---------- live lab for the website (poc-lab.js calls run(scenario)) ----------\ndef _ev(frm, to, label, log, state=\"\", ok=False, bad=False):\n    return {\"frm\": frm, \"to\": to, \"label\": label, \"log\": log, \"state\": state, \"ok\": ok, \"bad\": bad}\n\ndef run(sc):\n    \"\"\"Scenarios: prose | paraphrase | code | student.\"\"\"\n    ev, ck = [], []\n    if sc == \"prose\":\n        r = lab_prose()\n        ev += [_ev(\"M\", \"W\", \"sign\", f\"{r['answers']} prose answers of {r['tokens']} tokens, green-list bias {DELTA} on {int(GAMMA*100)}% of the vocabulary\", \"סימון\"),\n               _ev(\"W\", \"D\", \"detect\", f\"detected in {r['detected_pct']}% (mean z = {r['mean_z']}, threshold {Z_TH})\", f\"{r['detected_pct']}%\", ok=r[\"detected_pct\"] >= 90),\n               _ev(\"P\", \"D\", \"false\", f\"text written without the watermark flagged: {r['false_alarm_pct']}%\", f\"{r['false_alarm_pct']}%\", ok=r[\"false_alarm_pct\"] <= 2)]\n        ck += [[\"prose_detected\", r[\"detected_pct\"] >= 90], [\"no_false_alarms\", r[\"false_alarm_pct\"] <= 2]]\n    elif sc == \"paraphrase\":\n        r = lab_paraphrase()\n        ev += [_ev(\"W\", \"X\", \"rewrite\", f\"the same answers, {r['replaced_pct']}% of tokens rewritten\", \"ניסוח מחדש\"),\n               _ev(\"X\", \"D\", \"detect\", f\"detected in {r['detected_pct']}% (mean z = {r['mean_z']})\", f\"{r['detected_pct']}%\", bad=r[\"detected_pct\"] < 80)]\n        ck += [[\"paraphrase_measured\", True]]\n    elif sc == \"code\":\n        r = lab_code()\n        ev += [_ev(\"M\", \"W\", \"sign\", f\"{r['answers']} code-like answers of {r['tokens']} tokens: the next token is usually nearly certain\", \"סימון\"),\n               _ev(\"W\", \"D\", \"detect\", f\"detected in {r['detected_pct']}% (mean z = {r['mean_z']})\", f\"{r['detected_pct']}%\", bad=r[\"detected_pct\"] < 80),\n               _ev(\"W\", \"D\", \"longer\", f\"even at 1,000 tokens: {r['detected_1000_pct']}%\", f\"{r['detected_1000_pct']}%\", bad=r[\"detected_1000_pct\"] < 80)]\n        ck += [[\"code_survives\", r[\"detected_pct\"] >= 80]]\n    elif sc == \"student\":\n        r = lab_student()\n        ev += [_ev(\"W\", \"S\", \"train\", f\"a student trained on a corpus where {r['our_share_pct']}% is our watermarked text\", \"תלמיד\"),\n               _ev(\"S\", \"D\", \"short\", f\"student prose, 200-token answers: detected in {r['prose_200_pct']}%\", f\"{r['prose_200_pct']}%\", bad=r[\"prose_200_pct\"] < 80),\n               _ev(\"S\", \"D\", \"long\", f\"student prose, 3,000-token samples: {r['prose_3000_pct']}% (the signal is inherited, in long prose)\", f\"{r['prose_3000_pct']}%\", ok=r[\"prose_3000_pct\"] >= 80),\n               _ev(\"S\", \"D\", \"code\", f\"student code, 3,000-token samples: {r['code_3000_pct']}%\", f\"{r['code_3000_pct']}%\", bad=r[\"code_3000_pct\"] < 80)]\n        ck += [[\"student_measured\", True], [\"code_student_detected\", r[\"code_3000_pct\"] >= 80]]\n    return {\"events\": ev, \"checks\": ck}\n\nif __name__ == \"__main__\":\n    print(json.dumps(run_all(), indent=1, ensure_ascii=False))\n"});
